class Solution {
    public boolean isStraight(int[] cards) {
        int lo = Integer.MAX_VALUE;
        for (int c : cards) lo = Math.min(lo, c);
        for (int t = 1; t < cards.length; t++) {
            boolean found = false;
            for (int c : cards) if (c == lo + t) { found = true; break; }
            if (!found) return false;
        }
        return true;
    }
}

