    memcpy(s, cards, cardsSize * sizeof(int));
    qsort(s, cardsSize, sizeof(int), cmpInt);
    bool ok = true;
    for (int i = 0; i + 1 < cardsSize && ok; i++) {
        ok = (long long) s[i + 1] - s[i] == 1;
    }
    free(s);
    return ok;
