class Solution:
    def isStraight(self, cards: List[int]) -> bool:
        n = len(cards)
        lo, hi = min(cards), max(cards)
        if hi - lo != n - 1:
            return False
        seen = [False] * n
        for c in cards:
            if seen[c - lo]:
                return False
            seen[c - lo] = True
        return True

