class Solution {
    public boolean isStraight(int[] cards) {
        int n = cards.length;
        int lo = Integer.MAX_VALUE, hi = Integer.MIN_VALUE;
        for (int c : cards) { lo = Math.min(lo, c); hi = Math.max(hi, c); }
        if ((long) hi - lo != n - 1) return false;
        boolean[] seen = new boolean[n];
        for (int c : cards) {
            if (seen[c - lo]) return false;
            seen[c - lo] = true;
        }
        return true;
    }
}

