bool isStraight(int* cards, int cardsSize) {
    int lo = cards[0], hi = cards[0];
    for (int i = 1; i < cardsSize; i++) {
        if (cards[i] < lo) lo = cards[i];
        if (cards[i] > hi) hi = cards[i];
    }
    if ((long long) hi - lo != cardsSize - 1) return false;
    bool* seen = calloc(cardsSize, sizeof(bool));
    bool ok = true;
    for (int i = 0; i < cardsSize && ok; i++) {
        if (seen[cards[i] - lo]) ok = false;
        seen[cards[i] - lo] = true;
    }
    free(seen);
    return ok;
}
